<?php

declare(strict_types=1);

/**
 * Post-generation normalizer for flatc-emitted PHP.
 *
 * The FlatBuffers PHP codegen has a few long-standing defects that leak wrong
 * types into the rest of the app. Rather than hand-editing the generated files
 * (which every `composer flatbuffers` run would overwrite), this script re-applies
 * a fixed set of deterministic, idempotent transforms right after `flatc`, so the
 * generated tables come out correct and the proxies need no `@var int` band-aids.
 *
 * Transforms (only on files carrying the flatc "automatically generated" header):
 *
 *  1. Builder class casing. Upstream declares `Google\FlatBuffers\FlatbufferBuilder`
 *     (lower "b"); flatc references `FlatBufferBuilder` (capital "B"), which fails
 *     PSR-4 autoload on case-sensitive filesystems. Normalize to the real casing so
 *     no bootstrap shim is needed.
 *
 *  2. `create<Table>()` return docblock. flatc annotates `@return <Table>` on a
 *     method that actually returns the int table offset, poisoning every caller's
 *     inferred type. Rewrite it to `@return int`.
 *
 *  3. Single child-table accessors. flatc emits `... : 0` for an absent child table
 *     (an `int` where an object is expected), producing a `<Child>|int` union.
 *     Rewrite the `: 0` sentinel to `: null` so the accessor is `?<Child>`.
 *
 * Usage: php bin/patch-flatbuffers.php   (invoked by the composer `flatbuffers` script)
 */

$root = dirname(__DIR__);
$fbsDir = $root . '/src/API/Fbs';

if (!is_dir($fbsDir)) {
    fwrite(STDERR, "FlatBuffers output dir not found: $fbsDir\n");
    exit(1);
}

$iterator = new RecursiveIteratorIterator(
    new RecursiveDirectoryIterator($fbsDir, FilesystemIterator::SKIP_DOTS),
);

$patched = 0;

/** @var SplFileInfo $file */
foreach ($iterator as $file) {
    if ($file->getExtension() !== 'php') {
        continue;
    }

    $code = (string) file_get_contents($file->getPathname());

    // Only touch flatc-generated tables, never the hand-written proxies/contracts.
    if (!str_contains($code, 'automatically generated by the FlatBuffers compiler')) {
        continue;
    }

    $original = $code;

    // 1. builder class casing (case-sensitive match: only the capital-"B" spelling).
    $code = str_replace('FlatBufferBuilder', 'FlatbufferBuilder', $code);

    // 2. create<Table>() docblock: @return <Table> -> @return int. Keyed on the
    //    docblock terminator immediately preceding `public static function create`,
    //    so vector helpers (@return int vector offset) and getRootAs/init are left
    //    untouched.
    $code = preg_replace(
        '/(\*\s*@return\s+)\S+(\s*\n\s*\*\/\s*\n\s*public static function create)/',
        '${1}int${2}',
        $code,
    );

    // 3. single child-table accessor sentinel: `$obj->init(...) : 0;` -> `: null;`.
    //    Vector accessors already return null; scalar/enum accessors keep their
    //    numeric/enum defaults (they do not go through `$obj->init`).
    $code = preg_replace(
        '/(return \$o != 0 \? \$obj->init\([^;]*?\)) : 0;/',
        '$1 : null;',
        $code,
    );

    // 4. FlatBuffers scalar names in docblocks are not PHP types, so PHPStan
    //    reports every one of them as a phpDoc parse error and infers nothing.
    //    Map them onto the PHP types they actually are.
    $code = preg_replace_callback(
        '/(\*\s*@return\s+)(double|float|byte|ubyte|short|ushort|int|uint|long|ulong|bool)\b/',
        static function (array $m): string {
            $phpType = match ($m[2]) {
                'double', 'float' => 'float',
                'bool' => 'bool',
                default => 'int',
            };

            return $m[1].$phpType;
        },
        $code,
    );

    // 5. String accessors come out untyped, which makes every caller see `mixed`
    //    and forces a cast in each proxy. They return the string or null, so say
    //    so natively.
    $code = preg_replace(
        '/(public function get\w+\(\)\n\s*\{\n\s*\$o = \$this->__offset\(\d+\);\n\s*return \$o != 0 \? \$this->__string\()/',
        '$1',
        $code,
    );
    $code = preg_replace_callback(
        '/public function (get\w+)\(\)(\n\s*\{\n\s*\$o = \$this->__offset\(\d+\);\n\s*return \$o != 0 \? \$this->__string\([^;]*?\) : null;)/',
        static fn (array $m): string => 'public function '.$m[1].'(): ?string'.$m[2],
        $code,
    );

    if ($code !== $original) {
        file_put_contents($file->getPathname(), $code);
        echo "patched: " . substr($file->getPathname(), strlen($root) + 1) . "\n";
        $patched++;
    }
}

echo "flatbuffers patch complete ($patched file(s) changed).\n";
